  const landGeos = [];
  const box = (x0: number, x1: number, z0: number, z1: number, y0: number, y1: number) => { const b = new THREE.BoxGeometry(x1 - x0, y1 - y0, z1 - z0); b.translate((x0 + x1) / 2, (y0 + y1) / 2, (z0 + z1) / 2); return b; };
